using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<ModelTrainingService>();

// Train the model before building the app so the file exists for the pool
using var loggerFactory = LoggerFactory.Create(b => b.AddConsole());
var trainer = new ModelTrainingService(loggerFactory.CreateLogger<ModelTrainingService>());
var metrics = trainer.TrainAndEvaluate();

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

var app = builder.Build();
app.MapControllers();
app.MapGet("/api/model/metrics", () => Results.Ok(metrics));

app.Run();

